mapper.update:
UPDATE attendance_group_assignment current_row
SET current_row.effective_from = #{cutoff}
WHERE current_row.effective_from > #{cutoff}
  AND current_row.effective_from = (
        SELECT earliest
        FROM (
            SELECT MIN(other.effective_from) AS earliest
            FROM attendance_group_assignment other
            WHERE other.employee_id = current_row.employee_id
        ) nested)

UPDATE work_calendar_version
SET effective_from = #{cutoff}
WHERE calendar_year = YEAR(#{cutoff})
  AND effective_from > #{cutoff}

