INSERT INTO identity_effective_from_cutover_run (
    run_id, request_id, actor_id, change_reason, cutoff_date,
    status, updated_count, refused_count, created_at
) VALUES (
    #{runId}, #{requestId}, #{actorId}, #{reason}, #{cutoff},
    #{status}, #{updatedCount}, #{refusedCount}, #{createdAt}
)

INSERT INTO identity_effective_from_cutover_item (
    item_id, run_id, object_type, object_id, owner_id,
    old_effective_from, new_effective_from
) VALUES (
    #{itemId}, #{runId}, #{objectType}, #{objectId}, #{ownerId},
    #{oldFrom}, #{newFrom}
)

mapper.select:
SELECT status
FROM identity_effective_from_cutover_run
WHERE actor_id = #{actorId}
  AND request_id = #{requestId}
ORDER BY created_at DESC
LIMIT 1
